CREATE TABLE `tb_usuario` (
  `ID_Usuario` int(11) NOT NULL AUTO_INCREMENT,
  `Nombre` varchar(50) NOT NULL,
  `ApellidoPaterno` varchar(50) NOT NULL,
  `ApellidoMaterno` varchar(50) DEFAULT NULL,
  `NombreUsuario` varchar(30) NOT NULL,
  `CorreoElectronico` varchar(100) NOT NULL,
  `Contrasena` varchar(100) NOT NULL,
  `Rol` enum('Administrador','Usuario') NOT NULL,
  `Estado` enum('Activo','Inactivo') NOT NULL,
  `Tema` varchar(20) DEFAULT NULL,
  `Notificaciones` tinyint(1) DEFAULT NULL,
  `FotoPerfil` mediumblob DEFAULT NULL,
  `NotifMantenimiento` tinyint(1) NOT NULL DEFAULT 1,
  `NotifRecordatorios` tinyint(1) NOT NULL DEFAULT 1,
  `NotifReportes` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`ID_Usuario`),
  UNIQUE KEY `NombreUsuario` (`NombreUsuario`),
  UNIQUE KEY `CorreoElectronico` (`CorreoElectronico`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
